def run_batch(name, jobs):
    jobs = list({c.id: c for c in jobs}.values())
    pending = []
    status = {}
    active = {}
    results = {}
    fatal = []
    pointer = 0
    status_path = RESULTS / f'{name}_status.json'
    for c in jobs:
        if (c.output / 'summary.json').exists():
            r = verify(c)
            results[c.id] = r
            status[c.id] = dict(**c.values(), status=r['status'], reused=True)
        elif c.output.exists():
            raise RuntimeError(f'Partial run requires inspection: {c.output}')
        else:
            pending.append(c)
            status[c.id] = dict(**c.values(), status='pending')
    save_json(status_path, status)
    update_report(jobs, status)
    last_sample = 0
    while pending or active:
        for key, (c, p, gpu, log) in list(active.items()):
            rc = p.poll()
            if rc is None:
                continue
            log.close()
            del active[key]
            try:
                raw = read(c.output / 'summary.json')
                reusable = rc == 0 and raw['status'] == 'completed' or (raw['status'] == 'non_finite' and c.stage in ('search', 'review'))
                if not reusable:
                    raise RuntimeError(f"Worker {raw['status']}: {raw.get('error')}")
                seal(c)
                row = verify(c)
                if rc != 0 and row['status'] != 'non_finite':
                    raise RuntimeError(f'Worker exit {rc}')
                results[key] = row
                status[key].update(status=row['status'], exit_code=rc, ended=time.time())
            except Exception as error:
                fatal.append(str(error))
                failure = read(c.output / 'summary.json') if (c.output / 'summary.json').exists() else {}
                status[key].update(status='oom' if failure.get('status') == 'oom' else 'failed', worker_status=failure.get('status'), exit_code=rc, error=str(error), ended=time.time())
            event(batch=name, event='finished', **status[key])
            save_json(status_path, status)
            update_report(jobs, status)
        if not fatal and pending:
            occupied = gpu_processes()
            for gpu in (2, 3):
                own = {p.pid for c, p, g, log in active.values() if g == gpu}
                if occupied[gpu] - own:
                    continue
                existing = [c.task for c, p, g, log in active.values() if g == gpu]
                while True:
                    index = next((i for i, c in enumerate(pending) if capacity(c.task, existing)), None)
                    if index is None:
                        break
                    c = pending.pop(index)
                    c.output.mkdir(parents=True, exist_ok=True)
                    log = (c.output / 'train.log').open('a')
                    argv = [sys.executable, '-B', '/media/data/data/lt/dp-adam-correlated/exp16b/runtime/train_gpus_2_3.py', '--trial-json', json.dumps(c.values(), sort_keys=True)]
                    p = subprocess.Popen(argv, cwd=ROOT, env=dict(os.environ, CUDA_VISIBLE_DEVICES=str(gpu)), stdin=subprocess.DEVNULL, stdout=log, stderr=subprocess.STDOUT)
                    active[c.id] = (c, p, gpu, log)
                    existing.append(c.task)
                    status[c.id] = dict(**c.values(), status='running', gpu=gpu, pid=p.pid, started=time.time(), log=str(c.output / 'train.log'), command=f'CUDA_VISIBLE_DEVICES={gpu} ' + shlex.join(argv))
                    save_json(c.output / 'process.json', status[c.id])
                    event(batch=name, event='launched', **status[c.id])
                    save_json(status_path, status)
                    update_report(jobs, status)
                    print(f'{name}: GPU {gpu} {c.task} {c.method} pid={p.pid}', flush=True)
                pointer = (gpu + 1) % 4
        if active and time.time() - last_sample > 15:
            sample = subprocess.check_output(['nvidia-smi', '--query-gpu=index,utilization.gpu,memory.used', '--format=csv,noheader,nounits'], text=True)
            with (RESULTS / 'gpu_telemetry.jsonl').open('a') as f:
                f.write(json.dumps(dict(time=time.time(), batch=name, raw=sample, active=list(active))) + '\n')
            last_sample = time.time()
        if fatal and (not active):
            raise RuntimeError(f'{name} stopped without retry: ' + str(fatal))
        if pending or active:
            time.sleep(2)
    return [results[c.id] for c in jobs]
